const dec=`(∀ i : Chevalley.Index ell, Chevalley.J p M y v i.val = Chevalley.J p M y v 0) ∧ (Chevalley.J p M y v 0).FG ∧ Chevalley.J p M y v 0 ≠ ⊥ ∧ (∀ u : V, u ∈ Chevalley.image p M ↔ ∃! c : Chevalley.Index ell → ℂ, (∀ i, c i ∈ Chevalley.J p M y v 0) ∧ u = ∑ i, c i • Chevalley.e y v i.val)`;
