const reductions="Chevalley.reductions K p M";
const kform=`∃ β : Module.Basis (Chevalley.Index ell) K (Chevalley.VK K M), Chevalley.stringActions ell (Chevalley.opK K M x) (Chevalley.opK K M y) (Chevalley.opK K M h) (Chevalley.basisVec β) ∧ Chevalley.dividedActions ell (fun r => Chevalley.opK K M (Chevalley.dp x r)) (fun r => Chevalley.opK K M (Chevalley.dp y r)) (Chevalley.basisVec β) ∧ (∀ r : ℕ, r ≤ ell.toNat → (r.factorial : K) ≠ 0 ∧ Chevalley.opK K M (Chevalley.dp x r) = ((r.factorial : K)⁻¹) • Chevalley.opK K M x ^ r ∧ Chevalley.opK K M (Chevalley.dp y r) = ((r.factorial : K)⁻¹) • Chevalley.opK K M y ^ r) ∧ (∀ i j : Chevalley.Index ell, (Nat.choose ell.toNat j.val : K) ≠ 0 ∧ Chevalley.matrixK K ell M x y i j = Chevalley.unitOp β i j) ∧ (∀ W : Submodule K (Chevalley.VK K M), Chevalley.stable W (Chevalley.opK K M x) → Chevalley.stable W (Chevalley.opK K M y) → ∀ i j, Chevalley.stable W (Chevalley.matrixK K ell M x y i j))`;
